        var executionPins=new LinkedHashMap<Path,NextflowFiles.Pin>();for(String name:List.of("worker.py","codec.py","supervisor.py","request.json","runtime.original.json")){Path path=home.resolve(name);executionPins.put(path,NextflowFiles.pin(path,67108864,()->{}));}
